<?php $xtreampiSettings = is_array($rSettings ?? null) ? $rSettings : []; $xtreampiRedis = !empty($xtreampiSettings['redis_handler']); global $db; $xtreampiLineTotal = $xtreampiStreamTotal = $xtreampiSeriesTotal = 0; if (isset($db)) { $db->query('SELECT id FROM lines'); $xtreampiLineTotal = $db->num_rows(); $db->query('SELECT id FROM streams'); $xtreampiStreamTotal = $db->num_rows(); $db->query('SELECT id FROM streams_series'); $xtreampiSeriesTotal = $db->num_rows(); } $xtreampiCachedLines = defined('LINES_TMP_PATH') ? count(glob(LINES_TMP_PATH . 'line_i_*')) : 0; $xtreampiCachedStreams = defined('STREAMS_TMP_PATH') ? count(glob(STREAMS_TMP_PATH . 'stream_*')) : 0; $xtreampiCachedSeries = defined('SERIES_TMP_PATH') ? max(count(glob(SERIES_TMP_PATH . 'series_*')) - 2, 0) : 0; ?>
<section class="sc-cache"><div class="sc-page-heading"><div><p class="sc-eyebrow">System</p><h1>Cache &amp; Redis Settings</h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="settings?admin_ui=legacy">General Settings</a></div></div>
